    "image": "https://images.ctfassets.net/kgiutv51auvu/2kTrMXyEg33tMNyVScfoBZ/791b6e77904a94f779ac809f8cffc95c/exec-0c746225-e28e-41ba-92a4-1ebbd1884f9c.png",
    "imageAlt": "Forward-Deployed Engineer Building Production Systems",
